using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Text;
using System.Threading;
using SailwindRadio;
using SailwindRadio.Audio;
using SailwindRadio.Library;

// FLAC decoder checks. All source audio is synthetic and generated by Signal from integer math,
// so it is identical on every runtime. FLAC is lossless, so decoded integers must match exactly.
// Usage: FlacChecks [--regen] [--ffmpeg path]
// ffmpeg is --ffmpeg, then RADIO_CHECKS_FFMPEG, then ffmpeg on PATH. Without it the ffmpeg checks skip.
static class FlacChecks
{
    static int checks;
    static readonly List<string> skipped = new List<string>();
    static string testDir, fixtureDir, scratchDir, ffmpeg;
    // Bump when Signal or fixture specs change so cached scratch files are regenerated.
    const string ScratchVersion = "v1";

    static void Check(bool result, string message) { if (!result) throw new Exception("Check failed: " + message); checks++; }
    static void Skip(string what) { skipped.Add(what); Console.WriteLine("SKIP " + what); }

    static int Main(string[] args)
    {
        try
        {
            testDir = FindTestDir();
            fixtureDir = Path.Combine(testDir, "Fixtures");
            scratchDir = Path.GetFullPath(Path.Combine(testDir, "..", "..", ".local", "flac"));
            bool regen = false;
            string ffmpegArgument = null;
            for (int i = 0; i < args.Length; i++)
            {
                if (args[i] == "--regen") regen = true;
                else if (args[i] == "--ffmpeg" && i + 1 < args.Length) ffmpegArgument = args[++i];
            }
            ffmpeg = FindFfmpeg(ffmpegArgument);
            if (regen)
            {
                if (ffmpeg == null) throw new Exception("--regen needs ffmpeg");
                RegenerateFixtures();
                return 0;
            }
            var total = Stopwatch.StartNew();
            UnitChecks();
            FixtureChecks();
            EncoderFeatureChecks();
            MetadataChecks();
            ErrorChecks();
            SeekChecks();
            if (ffmpeg != null)
            {
                FfmpegMatrixChecks();
                LongFileChecks();
            }
            else
            {
                Skip("ffmpeg compression matrix (ffmpeg not found)");
                Skip("multi-minute seek checks (ffmpeg not found)");
                Skip("60-minute seek cost check (ffmpeg not found)");
                Skip("decode speed timing (ffmpeg not found)");
            }
            Console.WriteLine(checks + " FLAC checks passed in " + total.Elapsed.TotalSeconds.ToString("0.0") + " s on " + RuntimeName() +
                (skipped.Count == 0 ? ", none skipped" : ", " + skipped.Count + " skipped"));
            return 0;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine(ex);
            return 1;
        }
    }

    // An explicit path that does not exist skips the ffmpeg checks rather than falling back to PATH.
    static string FindFfmpeg(string argument)
    {
        string chosen = !string.IsNullOrEmpty(argument) ? argument : Environment.GetEnvironmentVariable("RADIO_CHECKS_FFMPEG");
        if (!string.IsNullOrEmpty(chosen)) return File.Exists(chosen) ? chosen : null;
        foreach (string dir in (Environment.GetEnvironmentVariable("PATH") ?? "").Split(Path.PathSeparator))
            foreach (string name in new[] { "ffmpeg.exe", "ffmpeg" })
            {
                try { string candidate = Path.Combine(dir.Trim().Trim('"'), name); if (File.Exists(candidate)) return candidate; }
                catch (ArgumentException) { }
            }
        return null;
    }

    static string RuntimeName() { return Type.GetType("Mono.Runtime") != null ? "Mono" : ".NET " + Environment.Version; }

    static string FindTestDir()
    {
        string dir = AppDomain.CurrentDomain.BaseDirectory;
        while (dir != null)
        {
            if (File.Exists(Path.Combine(dir, "FlacChecks.csproj"))) return dir;
            string nested = Path.Combine(dir, "tests", "Flac");
            if (File.Exists(Path.Combine(nested, "FlacChecks.csproj"))) return nested;
            dir = Path.GetDirectoryName(dir.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
        }
        throw new Exception("Cannot locate tests/Flac");
    }

    // ---- Unit checks ----

    static void UnitChecks()
    {
        byte[] digits = Encoding.ASCII.GetBytes("123456789");
        Check(FlacDecoder.Crc8(digits, 0, 9) == 0xF4 && TestCrc.Crc8(digits, 0, 9) == 0xF4, "CRC-8 polynomial 0x07 check value");
        Check(FlacDecoder.Crc16(digits, 0, 9) == 0xFEE8 && TestCrc.Crc16(digits, 0, 9) == 0xFEE8, "CRC-16 polynomial 0x8005 check value");

        // Coded numbers of every length, including the 36-bit seven byte form.
        long[] numbers = { 0, 127, 128, 2047, 2048, 65535, 65536, (1L << 21) - 1, 1L << 21, (1L << 26) - 1, 1L << 26, (1L << 31) - 1, 1L << 31, (1L << 36) - 1 };
        foreach (long number in numbers)
        {
            var w = new BitWriter();
            TestEncoder.WriteHeader(w, true, number, 4096, 44100, 1, 16, -1, true, true);
            byte[] header = w.ToArray();
            FlacDecoder.FrameHeader h;
            int status = FlacDecoder.TryParseHeader(header, 0, header.Length, out h);
            Check(status == FlacDecoder.HeaderOk && h.Number == number && h.Length == header.Length && h.Variable, "Variable coded sample number " + number);
            if (number < (1L << 31))
            {
                w = new BitWriter();
                TestEncoder.WriteHeader(w, false, number, 4096, 44100, 1, 16, -1, true, true);
                header = w.ToArray();
                Check(FlacDecoder.TryParseHeader(header, 0, header.Length, out h) == FlacDecoder.HeaderOk && h.Number == number, "Fixed coded frame number " + number);
            }
        }
        {
            var w = new BitWriter();
            TestEncoder.WriteHeader(w, false, 1L << 31, 4096, 44100, 1, 16, -1, true, true);
            byte[] header = w.ToArray();
            FlacDecoder.FrameHeader h;
            Check(FlacDecoder.TryParseHeader(header, 0, header.Length, out h) == FlacDecoder.HeaderInvalid, "Fixed frame numbers above 31 bits are rejected");
            header = new byte[] { 0xFF, 0xF8, 0x69, 0x08, 0xFF, 0, 0 };
            Check(FlacDecoder.TryParseHeader(header, 0, header.Length, out h) == FlacDecoder.HeaderInvalid, "Coded number lead byte 0xFF is rejected");
            header = new byte[] { 0xFF, 0xF8, 0xC9, 0x08, 0x00, 0x00 };
            Check(FlacDecoder.TryParseHeader(header, 0, header.Length, out h) == FlacDecoder.HeaderCrcMismatch, "Header CRC-8 mismatch is reported");
            header = new byte[] { 0xFF, 0xF8, 0x0F, 0x08, 0x00, 0x00 };
            Check(FlacDecoder.TryParseHeader(header, 0, header.Length, out h) == FlacDecoder.HeaderInvalid, "Reserved block size code is rejected");
            header = new byte[] { 0xFF, 0xF8, 0x6F, 0x08, 0x00, 0x00 };
            Check(FlacDecoder.TryParseHeader(header, 0, header.Length, out h) == FlacDecoder.HeaderInvalid, "Invalid sample rate code is rejected");
            header = new byte[] { 0xFF, 0xF8, 0x69, 0xB8, 0x00, 0x00 };
            Check(FlacDecoder.TryParseHeader(header, 0, header.Length, out h) == FlacDecoder.HeaderInvalid, "Reserved channel assignment is rejected");
            header = new byte[] { 0xFF, 0xF8, 0x69, 0x06, 0x00, 0x00 };
            Check(FlacDecoder.TryParseHeader(header, 0, header.Length, out h) == FlacDecoder.HeaderInvalid, "Reserved bit depth code is rejected");
            header = new byte[] { 0xFF, 0xFA, 0x69, 0x08, 0x00, 0x00 };
            Check(FlacDecoder.TryParseHeader(header, 0, header.Length, out h) == FlacDecoder.HeaderInvalid, "Reserved sync bit is rejected");
        }
        // The RFC 9639 layouts give exactly the coefficients FLAC had before the shared downmix.
        const double m3 = 0.70710678118654752;
        double[][] expectLeft =
        {
            new[] { 1, 0, m3 }, new[] { 1, 0, m3, 0 }, new[] { 1, 0, m3, m3, 0 }, new[] { 1, 0, m3, 0, m3, 0 },
            new[] { 1, 0, m3, 0, 0.5, m3, 0 }, new[] { 1, 0, m3, 0, m3, 0, m3, 0 },
        };
        double[][] expectRight =
        {
            new[] { 0, 1, m3 }, new[] { 0, 1, 0, m3 }, new[] { 0, 1, m3, 0, m3 }, new[] { 0, 1, m3, 0, 0, m3 },
            new[] { 0, 1, m3, 0, 0.5, 0, m3 }, new[] { 0, 1, m3, 0, 0, m3, 0, m3 },
        };
        for (int channels = 3; channels <= 8; channels++)
        {
            float[] l, r;
            ChannelDownmix.Build(ChannelDownmix.Flac(channels), out l, out r);
            double[] el = expectLeft[channels - 3], er = expectRight[channels - 3];
            double el1 = 0, er1 = 0;
            foreach (double w in el) el1 += w;
            foreach (double w in er) er1 += w;
            bool same = true;
            for (int c = 0; c < channels; c++) same &= l[c] == (float)(el[c] / el1) && r[c] == (float)(er[c] / er1);
            Check(same, "Shared downmix keeps the FLAC coefficients for " + channels + " channels");
            double sl = 0, sr = 0;
            for (int c = 0; c < channels; c++) { sl += Math.Abs(l[c]); sr += Math.Abs(r[c]); }
            Check(l.Length == channels && Math.Abs(sl - 1) < 1e-6 && Math.Abs(sr - 1) < 1e-6 && l[0] > l[2] && r[1] > r[2] && l[1] == 0 && r[0] == 0,
                "Downmix rows for " + channels + " channels sum to one and keep front channels on their side");
            if (channels >= 6) Check(l[3] == 0 && r[3] == 0, "Downmix drops LFE for " + channels + " channels");
        }
        Console.WriteLine("unit checks done");
    }

    // ---- Committed ffmpeg fixtures ----

    sealed class Fixture
    {
        public string Name, Args; public int Channels, Rate, Bits, Frames; public Signal Signal;
        public Action<Decoded> Expect;
        public Fixture(string name, int channels, int rate, int bits, int frames, Signal signal, string args, Action<Decoded> expect = null)
        { Name = name; Channels = channels; Rate = rate; Bits = bits; Frames = frames; Signal = signal; Args = args; Expect = expect; }
    }

    static Fixture[] Fixtures()
    {
        var mix = new Signal("mix", 1);
        var music = new Signal("music", 2);
        return new[]
        {
            new Fixture("mono16-l5", 1, 22050, 16, 22050, mix, "-compression_level 5", d => Check(d.Stats.Lpc > 0, "level 5 uses LPC subframes")),
            new Fixture("stereo16-l0", 2, 44100, 16, 22050, mix, "-compression_level 0", d => Check(d.Stats.Lpc == 0 && Sum(d.Stats.Fixed) > 0, "level 0 uses fixed predictors only")),
            new Fixture("stereo16-l8", 2, 44100, 16, 22050, mix, "-compression_level 8", d => Check(d.Stats.Lpc > 0, "level 8 uses LPC")),
            new Fixture("stereo16-l12", 2, 44100, 16, 22050, mix, "-compression_level 12", d => Check(d.Stats.Lpc > 0 && d.Stats.MaxLpcOrder > 12, "level 12 uses high LPC orders")),
            new Fixture("stereo16-leftside", 2, 32000, 16, 16000, music, "-ch_mode left_side", d => Check(d.Stats.ChannelModes[1] > 0, "left/side decorrelation exercised")),
            new Fixture("stereo16-rightside", 2, 32000, 16, 16000, music, "-ch_mode right_side", d => Check(d.Stats.ChannelModes[2] > 0, "right/side decorrelation exercised")),
            new Fixture("stereo16-midside", 2, 32000, 16, 16000, music, "-ch_mode mid_side", d => Check(d.Stats.ChannelModes[3] > 0, "mid/side decorrelation exercised")),
            new Fixture("stereo24-l5", 2, 48000, 24, 9600, music, "-compression_level 5 -sample_fmt s32 -bits_per_raw_sample 24", d => Check(d.Bits == 24, "24-bit stream")),
            new Fixture("stereo32", 2, 44100, 32, 4096, music, "-sample_fmt s32 -bits_per_raw_sample 32 -strict experimental", d => Check(d.Bits == 32, "32-bit stream")),
            new Fixture("stereo16-wasted8", 2, 22050, 16, 11025, new Signal("music", 3, 8), "-compression_level 5", d => Check(d.Stats.WastedBitsSubframes > 0, "wasted bits exercised")),
            new Fixture("surround51", 6, 22050, 16, 8000, music, "-ch_layout 5.1", d => Check(d.Src == 6 && d.Out == 2, "5.1 folds to stereo")),
            new Fixture("surround71", 8, 22050, 16, 6000, music, "-ch_layout 7.1", d => Check(d.Src == 8 && d.Out == 2, "7.1 folds to stereo")),
            new Fixture("mono16-frame192", 1, 8000, 16, 8000, mix, "-frame_size 192"),
            new Fixture("mono16-frame100", 1, 8000, 16, 8000, mix, "-frame_size 100"),
            new Fixture("mono16-frame1000", 1, 8000, 16, 8000, mix, "-frame_size 1000"),
            new Fixture("mono16-frame16384", 1, 8000, 16, 36000, music, "-frame_size 16384 -compression_level 5"),
            new Fixture("mono16-rate12000", 1, 12000, 16, 6000, music, ""),
            new Fixture("mono16-rate11025", 1, 11025, 16, 6000, music, ""),
            new Fixture("mono16-rate44110", 1, 44110, 16, 6000, music, ""),
            new Fixture("mono16-rate96000", 1, 96000, 16, 6000, music, ""),
            new Fixture("mono16-lpcnone", 1, 16000, 16, 8000, mix, "-lpc_type none"),
            new Fixture("mono16-cholesky", 1, 16000, 16, 8000, mix, "-lpc_type cholesky -compression_level 8"),
            new Fixture("stereo16-square", 2, 44100, 16, 8820, new Signal("square", 4), "", d => Check(MinFloat(d) == -1f, "full-scale negative square decodes to exactly -1")),
            new Fixture("stereo16-silence", 2, 44100, 16, 44100, new Signal("silence", 5), "", d => Check(d.Stats.Constant > 0 && d.Stats.Verbatim == 0, "silence uses constant subframes")),
        };
    }

    static long Sum(long[] values) { long s = 0; foreach (long v in values) s += v; return s; }
    static float MinFloat(Decoded d) { float m = 0; foreach (float f in d.Floats) if (f < m) m = f; return m; }

    static void RegenerateFixtures()
    {
        Directory.CreateDirectory(fixtureDir);
        string sourceDir = Path.Combine(scratchDir, "fixture-sources");
        Directory.CreateDirectory(sourceDir);
        long totalBytes = 0;
        foreach (var fx in Fixtures())
        {
            string wav = Path.Combine(sourceDir, fx.Name + ".wav");
            string flac = Path.Combine(fixtureDir, fx.Name + ".flac");
            WriteWav(wav, fx.Signal, fx.Channels, fx.Rate, fx.Bits, fx.Frames);
            RunFfmpeg(wav, flac, fx.Args);
            long size = new FileInfo(flac).Length;
            totalBytes += size;
            Console.WriteLine(fx.Name + ".flac " + size + " bytes");
        }
        Console.WriteLine("fixtures total " + totalBytes + " bytes");
    }

    static void FixtureChecks()
    {
        long totalBytes = 0;
        foreach (var fx in Fixtures())
        {
            string path = Path.Combine(fixtureDir, fx.Name + ".flac");
            Check(File.Exists(path), "Committed fixture exists " + fx.Name);
            byte[] data = File.ReadAllBytes(path);
            totalBytes += data.Length;
            Check(data.Length < 200 * 1024, "Fixture stays small " + fx.Name);
            var d = DecodeAll(data);
            Check(d.Src == fx.Channels && d.Rate == fx.Rate && d.Bits == fx.Bits && d.Frames == fx.Frames, "Stream properties " + fx.Name);
            CheckAgainst(d, fx.Signal, fx.Name);
            if (fx.Expect != null) fx.Expect(d);
        }
        Check(totalBytes < 1536 * 1024, "Committed fixtures total under 1.5 MB");
        Console.WriteLine("committed fixtures verified (" + totalBytes / 1024 + " KB)");
    }

    // ---- Test encoder feature coverage ----

    static void EncoderFeatureChecks()
    {
        var music = new Signal("music", 11);
        var mix = new Signal("mix", 12);
        var noise = new Signal("noise", 13);

        // Variable blocking over every block size code, all stereo modes and all subframe kinds.
        int[] allSizes = { 192, 576, 1152, 2304, 4608, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 100, 1000, 17, 16 };
        var d = EncodeDecode("8-bit variable", mix, 2, 48000, 8, 120000, new EncodeOptions { VariableSizes = allSizes, StereoMode = 11, Predictor = "cycle", Escape = true, PartitionOrder = 6 });
        Check(d.Stats.VariableFrames == d.Stats.Frames && d.Stats.Frames >= allSizes.Length, "Variable blocking frames decoded");
        for (int m = 0; m < 4; m++) Check(d.Stats.ChannelModes[m] > 0, "Stereo channel mode " + m + " exercised");
        for (int o = 0; o <= 4; o++) Check(d.Stats.Fixed[o] > 0, "Fixed order " + o + " exercised");
        Check(d.Stats.Verbatim > 0 && d.Stats.Lpc > 0 && d.Stats.Constant > 0 && d.Stats.EscapedPartitions > 0 && d.Stats.MaxLpcOrder == 32,
            "Verbatim, constant, LPC order 32 and escaped partitions exercised");

        d = EncodeDecode("4-bit mono", music, 1, 8000, 4, 20000, new EncodeOptions { BlockSize = 1152, Predictor = "cycle" });
        Check(d.Bits == 4, "4-bit depth from STREAMINFO");
        d = EncodeDecode("12-bit stereo", music, 2, 22050, 12, 20000, new EncodeOptions { BlockSize = 2048, StereoMode = 11, Predictor = "auto" });
        d = EncodeDecode("20-bit stereo", music, 2, 22050, 20, 20000, new EncodeOptions { BlockSize = 2048, StereoMode = 10, Predictor = "lpc8", Rice5 = true });
        Check(d.Stats.Rice5Partitions > 0, "Five-bit Rice parameters exercised");
        d = EncodeDecode("32-bit side channel", noise, 2, 44100, 32, 12000, new EncodeOptions { BlockSize = 1024, StereoMode = 11, Predictor = "cycle", Escape = true });
        Check(d.Stats.ChannelModes[1] > 0 && d.Stats.ChannelModes[3] > 0, "33-bit side channels decoded");
        d = EncodeDecode("32-bit full scale square", new Signal("square", 14), 2, 44100, 32, 5000, new EncodeOptions { BlockSize = 1024, StereoMode = 11, Predictor = "fixed2" });
        Check(MinFloat(d) == -1f, "32-bit minimum decodes to -1");
        d = EncodeDecode("24-bit wasted and loud residual", new Signal("noise", 15, 4), 2, 96000, 24, 12000, new EncodeOptions { BlockSize = 4096, Predictor = "fixed1" });
        Check(d.Stats.WastedBitsSubframes > 0 && d.Stats.Rice5Partitions > 0, "Wasted bits and large Rice parameters");
        d = EncodeDecode("LPC order 32 precision 15", music, 1, 44100, 16, 30000, new EncodeOptions { BlockSize = 4096, Predictor = "lpc32", LpcPrecision = 15, LpcShift = 12, PartitionOrder = 8 });
        Check(d.Stats.MaxLpcOrder == 32, "LPC order 32");
        d = EncodeDecode("LPC order 1 precision 2 shift 0", music, 1, 44100, 16, 10000, new EncodeOptions { BlockSize = 4096, Predictor = "lpc1", LpcPrecision = 2, LpcShift = 0 });
        d = EncodeDecode("Partition order 15", music, 1, 44100, 16, 65536, new EncodeOptions { BlockSize = 32768, Predictor = "fixed1", PartitionOrder = 15 });
        d = EncodeDecode("Small blocks with multibyte frame numbers", music, 1, 8000, 16, 40000, new EncodeOptions { BlockSize = 16, Predictor = "fixed2" });
        Check(d.Stats.Frames == 2500, "2500 fixed frames need three byte frame numbers");
        d = EncodeDecode("Last block shorter", music, 2, 44100, 16, 10001, new EncodeOptions { BlockSize = 4096, StereoMode = 10 });

        // Sample rate header forms and STREAMINFO fallbacks.
        int[][] rates = { new[] { 12000, 12 }, new[] { 11025, 13 }, new[] { 44110, 14 }, new[] { 100000, 12 }, new[] { 655350, 14 }, new[] { 44100, 13 }, new[] { 22050, 0 } };
        foreach (int[] rate in rates)
        {
            d = EncodeDecode("Rate " + rate[0] + " code " + rate[1], music, 1, rate[0], 16, 3000, new EncodeOptions { BlockSize = 1000, RateCode = rate[1], HeaderBits = rate[1] != 0 });
            Check(d.Rate == rate[0], "Sample rate " + rate[0]);
        }

        // Unknown total length is recovered by scanning.
        byte[] unknown = TestEncoder.Encode(Source(music, 2, 50000, 16), new EncodeOptions { SampleRate = 44100, BlockSize = 4096, TotalSamples = false, StereoMode = 10 });
        d = DecodeAll(unknown);
        Check(d.Frames == 50000, "Total samples 0 recovered by scanning fixed stream");
        CheckAgainst(d, music, "unknown length fixed");
        unknown = TestEncoder.Encode(Source(music, 1, 50001, 16), new EncodeOptions { SampleRate = 44100, VariableSizes = new[] { 4000, 333, 1234 }, TotalSamples = false });
        d = DecodeAll(unknown);
        Check(d.Frames == 50001, "Total samples 0 recovered by scanning variable stream");

        // Multichannel independent streams fold down with the documented coefficients.
        for (int channels = 3; channels <= 8; channels++)
        {
            d = EncodeDecode(channels + " channels", music, channels, 22050, 16, 5000, new EncodeOptions { BlockSize = 1024, Predictor = "auto" });
            Check(d.Out == 2, channels + " channels fold to stereo");
        }
        for (int bits = 4; bits <= 32; bits++)
        {
            d = EncodeDecode(bits + "-bit stereo", bits % 2 == 0 ? music : noise, 2, 44100, bits, 3000, new EncodeOptions { BlockSize = 576, StereoMode = 11, Predictor = "cycle", Escape = bits % 3 == 0 });
            Check(d.Bits == bits, "Bit depth " + bits);
        }
        d = EncodeDecode("mono 24-bit", music, 1, 48000, 24, 5000, new EncodeOptions { BlockSize = 1024 });
        Check(d.Out == 1, "Mono stays mono");
        Console.WriteLine("test encoder feature coverage done");
    }

    static Decoded EncodeDecode(string name, Signal signal, int channels, int rate, int bits, int frames, EncodeOptions o)
    {
        o.Bits = bits;
        o.SampleRate = rate;
        byte[] data = TestEncoder.Encode(Source(signal, channels, frames, bits), o);
        var d = DecodeAll(data);
        Check(d.Src == channels && d.Rate == rate && d.Bits == bits && d.Frames == frames, "Encoded stream properties " + name);
        CheckAgainst(d, signal, name);
        return d;
    }

    // ---- Metadata and container checks ----

    static void MetadataChecks()
    {
        var music = new Signal("music", 21);
        string comment = "TITLE=Test Tone\u00e9|ARTIST=Nobody|ALBUM=Synthetic";
        var o = new EncodeOptions { Bits = 16, SampleRate = 44100, BlockSize = 4096, Comment = TestEncoder.VorbisComment("test vendor", comment.Split('|')), ExtraBlocks = true, SeekEvery = 4096 * 3 };
        byte[] plain = TestEncoder.Encode(Source(music, 2, 40000, 16), o);
        foreach (int id3Kind in new[] { 0, 1, 2, 3 })
        {
            byte[] data = id3Kind == 0 ? plain : Concat(Id3Tag(id3Kind), plain);
            var d = DecodeAll(data);
            Check(d.Frames == 40000, "Decode with ID3 prefix kind " + id3Kind + " and extra metadata blocks");
            CheckAgainst(d, music, "id3 " + id3Kind);
            byte[] packet = FlacMetadata.ReadVorbisCommentPacket(new MemoryStream(data), 65536);
            Check(packet != null && packet[0] == 3 && Encoding.ASCII.GetString(packet, 1, 6) == "vorbis", "Vorbis comment packet found with ID3 kind " + id3Kind);
            string text = Encoding.UTF8.GetString(packet);
            Check(text.Contains("TITLE=Test Tone\u00e9") && text.Contains("ARTIST=Nobody") && text.Contains("ALBUM=Synthetic") && text.Contains("test vendor"), "Vorbis comment content");
            Check(FlacMetadata.ReadVorbisComment(new MemoryStream(data), 16) == null, "Oversized comment is refused");
        }
        using (var dec = new FlacDecoder(new MemoryStream(plain), CancellationToken.None))
            Check(dec.HasSeekTable, "Test encoder SEEKTABLE with placeholder parsed");
        byte[] noComment = TestEncoder.Encode(Source(music, 1, 1000, 16), new EncodeOptions { Bits = 16, SampleRate = 8000, BlockSize = 1000 });
        Check(FlacMetadata.ReadVorbisComment(new MemoryStream(noComment), 65536) == null, "Missing comment returns null");
        Check(FlacMetadata.ReadVorbisComment(new MemoryStream(Encoding.ASCII.GetBytes("RIFF....WAVE")), 65536) == null, "Non-FLAC returns null comment");
        string ffmpegFixture = Path.Combine(fixtureDir, "stereo16-l0.flac");
        byte[] ffPacket = FlacMetadata.ReadVorbisCommentPacket(File.OpenRead(ffmpegFixture), 65536);
        Check(ffPacket != null && Encoding.ASCII.GetString(ffPacket).Contains("encoder=Lavf"), "ffmpeg Vorbis comment read");
        Console.WriteLine("metadata checks done");
    }

    static byte[] Id3Tag(int kind)
    {
        // Kind 1: plain v2.4, 2: with footer, 3: two stacked tags.
        var list = new List<byte>();
        int count = kind == 3 ? 2 : 1;
        for (int t = 0; t < count; t++)
        {
            int size = 300 + t;
            bool footer = kind == 2;
            list.AddRange(new byte[] { (byte)'I', (byte)'D', (byte)'3', 4, 0, (byte)(footer ? 0x10 : 0),
                (byte)((size >> 21) & 0x7F), (byte)((size >> 14) & 0x7F), (byte)((size >> 7) & 0x7F), (byte)(size & 0x7F) });
            list.AddRange(new byte[size]);
            if (footer) list.AddRange(new byte[] { (byte)'3', (byte)'D', (byte)'I', 4, 0, 0x10, (byte)((size >> 21) & 0x7F), (byte)((size >> 14) & 0x7F), (byte)((size >> 7) & 0x7F), (byte)(size & 0x7F) });
        }
        return list.ToArray();
    }

    // ---- Error handling ----

    static void ErrorChecks()
    {
        byte[] good = File.ReadAllBytes(Path.Combine(fixtureDir, "stereo16-l8.flac"));
        int audioStart;
        var frames = IndexFrames(good, out audioStart);
        Check(frames.Count > 4, "Fixture frame index");
        var mid = frames[frames.Count / 2];

        byte[] bad = (byte[])good.Clone();
        bad[mid.Offset + mid.Size / 2] ^= 0x10;
        string message = DecodeError(bad);
        Check(message != null && message.Contains("CRC"), "Corrupted audio byte reports a CRC error: " + message);

        // After an error the decoder stays usable: the same frame fails again and seeking away recovers.
        using (var dec = new FlacDecoder(new MemoryStream(bad), CancellationToken.None))
        {
            var buffer = new float[4096];
            int errors = 0;
            dec.Seek(mid.Sample + 10);
            for (int attempt = 0; attempt < 2; attempt++)
                try { dec.Read(buffer, 0, buffer.Length); } catch (InvalidDataException) { errors++; }
            Check(errors == 2 && dec.Position == mid.Sample + 10, "Corrupt frame fails repeatedly without moving the position");
            dec.Seek(1234);
            Check(dec.Read(buffer, 0, 2) == 2 && buffer[0] == Expected(new Signal("mix", 1), 0, 1234, 16), "Seeking away from a corrupt frame recovers");
            dec.Seek(mid.Sample + mid.BlockSize + 5);
            Check(dec.Read(buffer, 0, 2) == 2 && buffer[1] == Expected(new Signal("mix", 1), 1, mid.Sample + mid.BlockSize + 5, 16), "Seeking past a corrupt frame recovers");
        }

        bad = (byte[])good.Clone();
        bad[mid.Offset + 4] ^= 0x01;
        message = DecodeError(bad);
        Check(message != null && (message.Contains("header") || message.Contains("CRC")), "Corrupted header byte reports an error: " + message);

        // Truncation anywhere gives a clear error, never a hang or an unrelated exception.
        long[] cuts = { 0, 2, 4, 10, 30, audioStart - 1, audioStart, audioStart + 3, mid.Offset, mid.Offset + mid.Size / 2, good.Length - 1 };
        foreach (long cut in cuts)
        {
            var sw = Stopwatch.StartNew();
            message = DecodeError(Slice(good, (int)cut));
            Check(message != null, "Truncated at " + cut + " is reported");
            Check(sw.ElapsedMilliseconds < 5000, "Truncated at " + cut + " fails quickly");
        }
        // With an unknown length a truncated stream ends cleanly after its last whole frame.
        byte[] zeroTotal = ZeroTotalSamples(good);
        var d = DecodeAll(Slice(zeroTotal, (int)(mid.Offset + mid.Size / 2)));
        Check(d.Frames == mid.Sample, "Unknown length truncated stream ends at last complete frame");
        CheckAgainst(d, new Signal("mix", 1), "truncated unknown length");

        Check(DecodeError(new byte[0]) == "File is not a FLAC stream", "Empty input rejected");
        Check(DecodeError(Encoding.ASCII.GetBytes("RIFF\0\0\0\0WAVEfmt ")) == "File is not a FLAC stream", "WAV input rejected");
        Check(DecodeError(Encoding.ASCII.GetBytes("fLaC")) == "FLAC metadata is truncated", "Marker only rejected");
        Check(DecodeError(Concat(Id3Tag(1), Encoding.ASCII.GetBytes("OggS garbage"))) == "File is not a FLAC stream", "ID3 then garbage rejected");
        Check(DecodeError(Concat(Encoding.ASCII.GetBytes("fLaC"), new byte[] { 0x84, 0, 0, 4, 0, 0, 0, 0 })) == "FLAC stream does not start with STREAMINFO", "Missing STREAMINFO rejected");
        var random = new byte[5000];
        new Random(7).NextBytes(random);
        Check(DecodeError(random) != null, "Random bytes rejected");
        try { new FlacDecoder(new NonSeekable(good), CancellationToken.None); Check(false, "Non-seekable stream rejected"); }
        catch (IOException ex) { Check(ex.Message.IndexOf(';') < 0, "Non-seekable stream rejected with IOException"); }

        // Decoder faults deliberately written by the test encoder.
        var music = new Signal("music", 31);
        string[] faults = { "negshift", "subtype", "method", "partition", "precision", "wasted" };
        string[] expected = { "negative LPC shift", "subframe type", "coding method", "partition order", "LPC precision", "wasted bits" };
        for (int i = 0; i < faults.Length; i++)
        {
            byte[] faulty = TestEncoder.Encode(Source(music, 1, 8192, 16), new EncodeOptions { Bits = 16, SampleRate = 44100, BlockSize = 4096, Predictor = "lpc4", Fault = faults[i] });
            message = DecodeError(faulty);
            Check(message != null && message.Contains(expected[i]), "Fault " + faults[i] + " rejected: " + message);
        }

        // Random corruption fuzz. Only InvalidDataException or IOException may escape, and quickly.
        byte[] small = TestEncoder.Encode(Source(new Signal("mix", 32), 2, 20000, 16), new EncodeOptions { Bits = 16, SampleRate = 44100, BlockSize = 1152, StereoMode = 11, Predictor = "cycle", Escape = true, SeekEvery = 5000 });
        var rng = new Random(1234);
        int failures = 0, successes = 0;
        var fuzzTime = Stopwatch.StartNew();
        for (int iteration = 0; iteration < 400; iteration++)
        {
            byte[] fuzz = (byte[])small.Clone();
            int flips = 1 + rng.Next(3);
            // Every fourth case targets metadata and the first frame headers.
            int range = iteration % 4 == 3 ? 300 : fuzz.Length;
            for (int f = 0; f < flips; f++) fuzz[rng.Next(range)] ^= (byte)(1 << rng.Next(8));
            if (iteration % 5 == 0) fuzz = Slice(fuzz, rng.Next(fuzz.Length));
            try
            {
                using (var dec = new FlacDecoder(new MemoryStream(fuzz), CancellationToken.None))
                {
                    var buffer = new float[4096];
                    if (iteration % 2 == 1 && dec.Frames > 0) dec.Seek(rng.Next((int)Math.Min(dec.Frames, int.MaxValue)));
                    long guard = 0;
                    while (dec.Read(buffer, 0, buffer.Length) > 0) if (++guard > 1000000) throw new Exception("fuzz decode does not end");
                }
                successes++;
            }
            catch (InvalidDataException ex) { failures++; Check(ex.Message.IndexOf(';') < 0, "Error messages carry no semicolons"); }
            catch (IOException) { failures++; }
        }
        Check(fuzzTime.ElapsedMilliseconds < 60000, "Fuzz finishes promptly");
        Check(failures > 0, "Fuzz corruptions were detected");
        Console.WriteLine("error checks done (fuzz " + failures + " rejected, " + successes + " decoded cleanly, " + fuzzTime.ElapsedMilliseconds + " ms)");

        // Cancellation stops construction and decoding.
        using (var cts = new CancellationTokenSource())
        {
            var dec = new FlacDecoder(new MemoryStream(good), cts.Token);
            cts.Cancel();
            bool cancelled = false;
            try { dec.Read(new float[8192], 0, 8192); } catch (OperationCanceledException) { cancelled = true; }
            Check(cancelled, "Cancellation token stops decoding");
            bool threw = false;
            try { new FlacDecoder(new MemoryStream(good), cts.Token); } catch (OperationCanceledException) { threw = true; }
            Check(threw, "Cancellation token stops construction");
        }
    }

    static string DecodeError(byte[] data)
    {
        try
        {
            using (var d = new FlacDecoder(new MemoryStream(data), CancellationToken.None))
            {
                var buffer = new float[8192];
                while (d.Read(buffer, 0, buffer.Length) > 0) { }
            }
            return null;
        }
        catch (InvalidDataException ex) { return ex.Message; }
        catch (IOException ex) { return ex.Message; }
    }

    sealed class NonSeekable : MemoryStream
    {
        public NonSeekable(byte[] data) : base(data) { }
        public override bool CanSeek { get { return false; } }
    }

    // ---- Seeking on small streams ----

    static void SeekChecks()
    {
        var mix = new Signal("mix", 41);
        long frames = 200000;
        byte[] withTable = TestEncoder.Encode(Source(mix, 2, frames, 16), new EncodeOptions { Bits = 16, SampleRate = 44100, BlockSize = 4096, StereoMode = 11, Predictor = "auto", SeekEvery = 44100 });
        byte[] variable = TestEncoder.Encode(Source(mix, 2, frames, 16), new EncodeOptions { Bits = 16, SampleRate = 44100, VariableSizes = new[] { 4096, 1000, 2500, 333 }, StereoMode = 10 });
        byte[] fixture = File.ReadAllBytes(Path.Combine(fixtureDir, "mono16-frame192.flac"));
        SeekSeries("encoded with SEEKTABLE", withTable, mix, 2, frames, 60, true);
        SeekSeries("encoded without SEEKTABLE", StripSeekTable(withTable), mix, 2, frames, 60, false);
        SeekSeries("variable blocking", variable, mix, 2, frames, 60, false);
        SeekSeries("unknown length", ZeroTotalSamples(StripSeekTable(withTable)), mix, 2, frames, 30, false);
        SeekSeries("ffmpeg small frames", fixture, new Signal("mix", 1), 1, 8000, 30, false);
        using (var d = new FlacDecoder(new MemoryStream(withTable), CancellationToken.None))
        {
            var buffer = new float[1000];
            d.Seek(frames + 500);
            Check(d.Position == frames && d.Read(buffer, 0, buffer.Length) == 0, "Seek past end clamps and reads nothing");
            d.Seek(frames);
            Check(d.Read(buffer, 0, buffer.Length) == 0, "Seek to end reads nothing");
            d.Seek(frames - 1);
            Check(d.Read(buffer, 0, buffer.Length) == 2 && d.Position == frames, "Seek to last frame reads one frame");
            Check(buffer[0] == Expected(mix, 0, frames - 1, 16), "Last frame value");
            d.Seek(0);
            Check(d.Read(buffer, 0, 3) == 2 && buffer[0] == Expected(mix, 0, 0, 16), "Seek to zero and odd count reads whole frames only");
            bool threw = false;
            try { d.Seek(-1); } catch (ArgumentOutOfRangeException) { threw = true; }
            Check(threw, "Negative seek rejected");
            Check(d.Read(buffer, 0, 1) == 0 && d.Position == 1, "Count below one frame reads nothing without advancing");
            d.Seek(1000);
            buffer[4] = 7;
            Check(d.Read(buffer, 5, 4) == 4 && buffer[4] == 7 && buffer[5] == Expected(mix, 0, 1000, 16) && buffer[8] == Expected(mix, 1, 1001, 16), "Read honours the output offset");
            threw = false;
            try { d.Read(buffer, 999, 2); } catch (ArgumentOutOfRangeException) { threw = true; }
            Check(threw, "Read range beyond the buffer rejected");
        }
        Console.WriteLine("small seek checks done");
    }

    static void SeekSeries(string name, byte[] data, Signal signal, int channels, long frames, int count, bool expectTable)
    {
        using (var d = new FlacDecoder(new MemoryStream(data), CancellationToken.None))
        {
            Check(d.Frames == frames && d.HasSeekTable == expectTable, "Seek stream properties " + name);
            var rng = new Random(99);
            var buffer = new float[3000 * channels];
            long last = -1;
            for (int i = 0; i < count; i++)
            {
                long target = i == 0 ? 0 : i == 1 ? frames - 1 : i == 2 ? last : i % 7 == 0 && last >= 0 ? Math.Min(frames - 1, last + 10) : (long)(rng.NextDouble() * frames);
                if (target < 0) target = 0;
                d.Seek(target);
                Check(d.Position == target, "Position after seek " + name);
                int got = d.Read(buffer, 0, buffer.Length);
                long expectFrames = Math.Min(3000, frames - target);
                Check(got == expectFrames * channels, "Read length after seek " + name + " to " + target);
                for (long f = 0; f < expectFrames; f++)
                    for (int c = 0; c < channels; c++)
                        if (buffer[f * channels + c] != Expected(signal, c, target + f, 16)) Check(false, "Seek " + name + " to " + target + " sample " + (target + f));
                last = target;
            }
            checks++;
        }
    }

    static float Expected(Signal s, int ch, long i, int bits) { return (float)s.At(ch, i, bits) * (float)(1.0 / (1L << (bits - 1))); }

    // ---- ffmpeg matrix (scratch) ----

    static void FfmpegMatrixChecks()
    {
        string dir = Path.Combine(scratchDir, ScratchVersion + "-matrix");
        Directory.CreateDirectory(dir);
        var mix = new Signal("mix", 51);
        var list = new List<Fixture>();
        for (int level = 0; level <= 12; level++) list.Add(new Fixture("level" + level, 2, 44100, 16, 88200, mix, "-compression_level " + level));
        foreach (string lpc in new[] { "none", "fixed", "levinson", "cholesky" }) list.Add(new Fixture("lpc-" + lpc, 2, 44100, 16, 44100, mix, "-lpc_type " + lpc));
        foreach (string mode in new[] { "indep", "left_side", "right_side", "mid_side" }) list.Add(new Fixture("chmode-" + mode, 2, 44100, 16, 44100, mix, "-ch_mode " + mode));
        foreach (int size in new[] { 16, 192, 576, 1152, 2304, 4096, 4608, 8192, 32768, 65535 }) list.Add(new Fixture("frame" + size, 1, 44100, 16, 100000, mix, "-frame_size " + size));
        list.Add(new Fixture("s24-l8", 2, 96000, 24, 48000, mix, "-compression_level 8 -sample_fmt s32 -bits_per_raw_sample 24"));
        list.Add(new Fixture("s32-l8", 2, 48000, 32, 48000, mix, "-compression_level 8 -sample_fmt s32 -bits_per_raw_sample 32 -strict experimental"));
        list.Add(new Fixture("partition8", 2, 44100, 16, 44100, mix, "-min_partition_order 8 -max_partition_order 8"));
        list.Add(new Fixture("rice-exact", 2, 44100, 16, 44100, new Signal("noise", 52), "-exact_rice_parameters 1 -compression_level 8"));
        foreach (var layout in new[] { new[] { "3", "3.0" }, new[] { "4", "quad" }, new[] { "5", "5.0" }, new[] { "6", "5.1" }, new[] { "7", "6.1" }, new[] { "8", "7.1" } })
            list.Add(new Fixture("layout" + layout[1], int.Parse(layout[0]), 48000, 16, 24000, mix, "-ch_layout " + layout[1]));
        int done = 0;
        foreach (var fx in list)
        {
            string flac = Path.Combine(dir, fx.Name + ".flac");
            if (!File.Exists(flac))
            {
                string wav = Path.Combine(dir, fx.Name + ".wav");
                WriteWav(wav, fx.Signal, fx.Channels, fx.Rate, fx.Bits, fx.Frames);
                try { RunFfmpeg(wav, flac, fx.Args); }
                catch (Exception ex) { Skip("ffmpeg case " + fx.Name + " (" + ex.Message.Split('\n')[0].Trim() + ")"); continue; }
                finally { File.Delete(wav); }
            }
            var d = DecodeAll(File.ReadAllBytes(flac));
            Check(d.Src == fx.Channels && d.Frames == fx.Frames && d.Bits == fx.Bits, "ffmpeg stream properties " + fx.Name);
            CheckAgainst(d, fx.Signal, "ffmpeg " + fx.Name);
            if (fx.Name.StartsWith("chmode-") && fx.Name != "chmode-indep")
                Check(d.Stats.ChannelModes[fx.Name == "chmode-left_side" ? 1 : fx.Name == "chmode-right_side" ? 2 : 3] > 0, "ffmpeg forced mode used " + fx.Name);
            done++;
        }
        Console.WriteLine("ffmpeg matrix verified (" + done + " encodes)");
    }

    // ---- Long files (scratch) ----

    static void LongFileChecks()
    {
        string dir = Path.Combine(scratchDir, ScratchVersion + "-long");
        Directory.CreateDirectory(dir);
        var mix = new Signal("mix", 61);
        long frames = 44100L * 300;
        string path = Path.Combine(dir, "stereo-5min.flac");
        if (!File.Exists(path))
        {
            string wav = Path.Combine(dir, "stereo-5min.wav");
            WriteWav(wav, mix, 2, 44100, 16, frames);
            RunFfmpeg(wav, path, "-compression_level 5");
            File.Delete(wav);
        }
        byte[] data = File.ReadAllBytes(path);

        // Decode speed, then a full lossless verification pass.
        double best = double.MaxValue;
        for (int pass = 0; pass < 2; pass++)
        {
            var sw = Stopwatch.StartNew();
            using (var d = new FlacDecoder(new MemoryStream(data), CancellationToken.None))
            {
                var buffer = new float[8192];
                while (d.Read(buffer, 0, buffer.Length) > 0) { }
            }
            best = Math.Min(best, sw.Elapsed.TotalSeconds);
        }
        double speed = 300.0 / best;
        Console.WriteLine("decode speed " + speed.ToString("0") + "x real time on " + RuntimeName() + " (5 min 44.1 kHz stereo 16-bit level 5, " + best.ToString("0.00") + " s)");
        Check(speed > 20, "Decode faster than 20x real time");
        using (var d = new FlacDecoder(new MemoryStream(data), CancellationToken.None))
        {
            Check(d.Frames == frames && !d.HasSeekTable, "ffmpeg long file has no SEEKTABLE");
            var buffer = new float[8190];
            long at = 0;
            int got;
            while ((got = d.Read(buffer, 0, buffer.Length)) > 0)
            {
                for (int i = 0; i < got; i += 2)
                    if (buffer[i] != Expected(mix, 0, at + i / 2, 16) || buffer[i + 1] != Expected(mix, 1, at + i / 2, 16)) Check(false, "Long file sample " + (at + i / 2));
                at += got / 2;
            }
            Check(at == frames, "Long file full decode length");
        }

        LongSeeks("5 min without SEEKTABLE", data, mix, 2, frames, false);
        LongSeeks("5 min with SEEKTABLE", InjectSeekTable(data, 44100 * 10), mix, 2, frames, true);
        var sw2 = Stopwatch.StartNew();
        LongSeeks("5 min unknown length", ZeroTotalSamples(data), mix, 2, frames, false);
        Console.WriteLine("unknown length variant with 50 seeks " + sw2.ElapsedMilliseconds + " ms");

        // A 60-minute stream must not decode from the start to seek.
        var music = new Signal("music", 62);
        long hour = 8000L * 3600;
        string hourPath = Path.Combine(dir, "mono-60min.flac");
        if (!File.Exists(hourPath))
        {
            string wav = Path.Combine(dir, "mono-60min.wav");
            WriteWav(wav, music, 1, 8000, 16, hour);
            RunFfmpeg(wav, hourPath, "-compression_level 5");
            File.Delete(wav);
        }
        byte[] hourData = File.ReadAllBytes(hourPath);
        LongSeeks("60 min without SEEKTABLE", hourData, music, 1, hour, false);
        LongSeeks("60 min with SEEKTABLE", InjectSeekTable(hourData, 8000 * 10), music, 1, hour, true);
        var scan = Stopwatch.StartNew();
        using (var d = new FlacDecoder(new MemoryStream(ZeroTotalSamples(hourData)), CancellationToken.None))
        {
            Check(d.Frames == hour && d.Statistics.Frames < 8, "60 min unknown length found by scanning the tail only");
        }
        Console.WriteLine("60 min unknown length scan " + scan.ElapsedMilliseconds + " ms");
        // File-backed stream, as the integrator will use.
        using (var d = new FlacDecoder(File.OpenRead(hourPath), CancellationToken.None))
        {
            var buffer = new float[100];
            d.Seek(hour - 50);
            Check(d.Read(buffer, 0, 100) == 50 && buffer[49] == Expected(music, 0, hour - 1, 16), "File stream seek near the end of 60 min");
        }
    }

    static void LongSeeks(string name, byte[] data, Signal signal, int channels, long frames, bool expectTable)
    {
        using (var d = new FlacDecoder(new MemoryStream(data), CancellationToken.None))
        {
            Check(d.Frames == frames && d.HasSeekTable == expectTable, "Long seek stream " + name);
            var rng = new Random(2024);
            var buffer = new float[2000 * channels];
            long maxFrames = 0;
            var sw = Stopwatch.StartNew();
            int count = 50;
            for (int i = 0; i < count; i++)
            {
                long target = i == 0 ? frames - 1 : i == 1 ? 0 : (long)(rng.NextDouble() * frames);
                long before = d.Statistics.Frames;
                d.Seek(target);
                int got = d.Read(buffer, 0, buffer.Length);
                maxFrames = Math.Max(maxFrames, d.Statistics.Frames - before);
                long n = Math.Min(2000, frames - target);
                Check(got == n * channels, "Long seek read length " + name);
                for (long f = 0; f < n; f++)
                    for (int c = 0; c < channels; c++)
                        if (buffer[f * channels + c] != Expected(signal, c, target + f, 16)) Check(false, "Long seek " + name + " to " + target);
            }
            Check(maxFrames < 120, "Seeks decode few frames " + name + " (max " + maxFrames + ")");
            Console.WriteLine("seek " + name + ": " + (sw.Elapsed.TotalMilliseconds / count).ToString("0.0") + " ms average, at most " + maxFrames + " frames decoded per seek");
        }
    }

    // ---- Decoding helpers ----

    sealed class Decoded
    {
        public long Frames; public int Src, Out, Bits, Rate;
        public long[][] Ints; public float[] Floats; public FlacStatistics Stats;
    }

    static Decoded DecodeAll(byte[] data)
    {
        using (var d = new FlacDecoder(new MemoryStream(data, false), CancellationToken.None))
        {
            var r = new Decoded { Frames = d.Frames, Src = d.SourceChannels, Out = d.Channels, Bits = d.BitsPerSample, Rate = d.SampleRate, Stats = d.Statistics };
            Check(r.Frames < 20000000, "Test decode size");
            long frames = r.Frames;
            r.Ints = new long[r.Src][];
            for (int c = 0; c < r.Src; c++) r.Ints[c] = new long[frames];
            d.FrameDecoded = (s, n, start, bits) =>
            {
                long limit = Math.Min(n, frames - start);
                for (int c = 0; c < s.Length; c++)
                    for (long i = 0; i < limit; i++) r.Ints[c][start + i] = s[c][i];
            };
            r.Floats = new float[frames * r.Out];
            // An odd buffer length checks that Read returns whole frames only.
            var buffer = new float[1531 * r.Out + 1];
            long at = 0;
            int got;
            while ((got = d.Read(buffer, 0, buffer.Length)) > 0)
            {
                if (got % r.Out != 0) Check(false, "Read returned a partial frame");
                Array.Copy(buffer, 0, r.Floats, at, got);
                at += got;
            }
            Check(at == frames * r.Out && d.Position == frames, "Decoded length matches Frames");
            return r;
        }
    }

    static void CheckAgainst(Decoded d, Signal s, string name)
    {
        for (int c = 0; c < d.Src; c++)
            for (long i = 0; i < d.Frames; i++)
                if (d.Ints[c][i] != s.At(c, i, d.Bits))
                    Check(false, name + " channel " + c + " sample " + i + " decoded " + d.Ints[c][i] + " expected " + s.At(c, i, d.Bits));
        float scale = (float)(1.0 / (1L << (d.Bits - 1)));
        if (d.Src <= 2)
        {
            for (long i = 0; i < d.Frames; i++)
                for (int c = 0; c < d.Src; c++)
                    if (d.Floats[i * d.Src + c] != (float)s.At(c, i, d.Bits) * scale) Check(false, name + " float sample " + i);
        }
        else
        {
            float[] l, r;
            ChannelDownmix.Build(ChannelDownmix.Flac(d.Src), out l, out r);
            for (long i = 0; i < d.Frames; i++)
            {
                double el = 0, er = 0;
                for (int c = 0; c < d.Src; c++) { double v = (float)s.At(c, i, d.Bits) * scale; el += l[c] * v; er += r[c] * v; }
                if (Math.Abs(d.Floats[i * 2] - el) > 2e-6 || Math.Abs(d.Floats[i * 2 + 1] - er) > 2e-6) Check(false, name + " downmix sample " + i);
            }
        }
        checks++;
    }

    static long[][] Source(Signal s, int channels, long frames, int bits)
    {
        var result = new long[channels][];
        for (int c = 0; c < channels; c++)
        {
            result[c] = new long[frames];
            for (long i = 0; i < frames; i++) result[c][i] = s.At(c, i, bits);
        }
        return result;
    }

    static byte[] Slice(byte[] data, int length) { var r = new byte[length]; Array.Copy(data, r, length); return r; }
    static byte[] Concat(byte[] a, byte[] b) { var r = new byte[a.Length + b.Length]; Array.Copy(a, r, a.Length); Array.Copy(b, 0, r, a.Length, b.Length); return r; }

    // ---- File rewriting ----

    sealed class Block { public int Type; public byte[] Data; }
    sealed class FrameInfo { public long Offset, Sample; public int Size, BlockSize; }

    static List<Block> ReadBlocks(byte[] f, out int audioStart)
    {
        var ms = new MemoryStream(f);
        AudioFiles.SkipId3v2(ms);
        int p = (int)ms.Position + 4;
        var blocks = new List<Block>();
        bool last = false;
        while (!last)
        {
            last = (f[p] & 0x80) != 0;
            int size = (f[p + 1] << 16) | (f[p + 2] << 8) | f[p + 3];
            var b = new Block { Type = f[p] & 0x7F, Data = new byte[size] };
            Array.Copy(f, p + 4, b.Data, 0, size);
            blocks.Add(b);
            p += 4 + size;
        }
        audioStart = p;
        return blocks;
    }

    static byte[] Assemble(List<Block> blocks, byte[] f, int audioStart)
    {
        var ms = new MemoryStream();
        ms.Write(Encoding.ASCII.GetBytes("fLaC"), 0, 4);
        for (int i = 0; i < blocks.Count; i++)
        {
            var b = blocks[i];
            ms.WriteByte((byte)(b.Type | (i == blocks.Count - 1 ? 0x80 : 0)));
            ms.WriteByte((byte)(b.Data.Length >> 16)); ms.WriteByte((byte)(b.Data.Length >> 8)); ms.WriteByte((byte)b.Data.Length);
            ms.Write(b.Data, 0, b.Data.Length);
        }
        ms.Write(f, audioStart, f.Length - audioStart);
        return ms.ToArray();
    }

    static byte[] ZeroTotalSamples(byte[] f)
    {
        int audioStart;
        var blocks = ReadBlocks(f, out audioStart);
        byte[] info = blocks[0].Data;
        info[13] &= 0xF0;
        info[14] = info[15] = info[16] = info[17] = 0;
        return Assemble(blocks, f, audioStart);
    }

    static byte[] StripSeekTable(byte[] f)
    {
        int audioStart;
        var blocks = ReadBlocks(f, out audioStart);
        blocks.RemoveAll(b => b.Type == 3);
        return Assemble(blocks, f, audioStart);
    }

    static byte[] InjectSeekTable(byte[] f, long every)
    {
        int audioStart;
        var frames = IndexFrames(f, out audioStart);
        var blocks = ReadBlocks(f, out audioStart);
        blocks.RemoveAll(b => b.Type == 3);
        var points = new List<FrameInfo>();
        long next = 0;
        foreach (var fr in frames)
            if (fr.Sample + fr.BlockSize > next) { points.Add(fr); next = (fr.Sample / every + 1) * every; }
        var table = new byte[(points.Count + 1) * 18];
        for (int i = 0; i < points.Count; i++)
        {
            PutBig(table, i * 18, points[i].Sample, 8);
            PutBig(table, i * 18 + 8, points[i].Offset - audioStart, 8);
            PutBig(table, i * 18 + 16, points[i].BlockSize, 2);
        }
        for (int b = 0; b < 8; b++) table[points.Count * 18 + b] = 0xFF; // Placeholder.
        blocks.Insert(1, new Block { Type = 3, Data = table });
        return Assemble(blocks, f, audioStart);
    }

    static void PutBig(byte[] b, int offset, long value, int bytes) { for (int i = bytes - 1; i >= 0; i--) { b[offset + i] = (byte)value; value >>= 8; } }

    // Frames found by sync, header CRC and consecutive numbering.
    static List<FrameInfo> IndexFrames(byte[] f, out int audioStart)
    {
        ReadBlocks(f, out audioStart);
        var list = new List<FrameInfo>();
        long expected = 0;
        int fixedSize = 0;
        int p = audioStart;
        while (p < f.Length - 2)
        {
            FlacDecoder.FrameHeader h;
            if (f[p] == 0xFF && FlacDecoder.TryParseHeader(f, p, Math.Min(16, f.Length - p), out h) == FlacDecoder.HeaderOk)
            {
                if (list.Count == 0) fixedSize = h.BlockSize;
                long sample = h.Variable ? h.Number : h.Number * fixedSize;
                if (sample == expected)
                {
                    if (list.Count > 0) list[list.Count - 1].Size = (int)(p - list[list.Count - 1].Offset);
                    list.Add(new FrameInfo { Offset = p, Sample = sample, BlockSize = h.BlockSize });
                    expected += h.BlockSize;
                    p += h.Length;
                    continue;
                }
            }
            p++;
        }
        if (list.Count > 0) list[list.Count - 1].Size = (int)(f.Length - list[list.Count - 1].Offset);
        return list;
    }

    // ---- WAV and ffmpeg ----

    static void WriteWav(string path, Signal s, int channels, int rate, int bits, long frames)
    {
        int bytes = bits / 8;
        long dataBytes = frames * channels * bytes;
        bool extensible = channels > 2 || bits > 16;
        int[] masks = { 0, 0x4, 0x3, 0x7, 0x33, 0x37, 0x3F, 0x70F, 0x63F };
        using (var w = new BinaryWriter(new BufferedStream(File.Create(path), 1 << 20)))
        {
            w.Write(Encoding.ASCII.GetBytes("RIFF"));
            w.Write((uint)(4 + 8 + (extensible ? 40 : 16) + 8 + dataBytes));
            w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));
            w.Write(extensible ? 40 : 16);
            w.Write((ushort)(extensible ? 0xFFFE : 1));
            w.Write((ushort)channels);
            w.Write(rate);
            w.Write(rate * channels * bytes);
            w.Write((ushort)(channels * bytes));
            w.Write((ushort)bits);
            if (extensible)
            {
                w.Write((ushort)22);
                w.Write((ushort)bits);
                w.Write(masks[channels]);
                w.Write(new byte[] { 1, 0, 0, 0, 0, 0, 0x10, 0, 0x80, 0, 0, 0xAA, 0, 0x38, 0x9B, 0x71 });
            }
            w.Write(Encoding.ASCII.GetBytes("data"));
            w.Write((uint)dataBytes);
            for (long i = 0; i < frames; i++)
                for (int c = 0; c < channels; c++)
                {
                    long v = s.At(c, i, bits);
                    if (bits == 8) w.Write((byte)(v + 128));
                    else for (int b = 0; b < bytes; b++) w.Write((byte)(v >> (8 * b)));
                }
        }
    }

    static void RunFfmpeg(string wav, string flac, string args)
    {
        var info = new ProcessStartInfo(ffmpeg, "-hide_banner -loglevel error -y -i \"" + wav + "\" -c:a flac " + args + " \"" + flac + "\"")
        {
            UseShellExecute = false,
            RedirectStandardError = true,
            RedirectStandardOutput = true,
            CreateNoWindow = true,
        };
        using (var process = Process.Start(info))
        {
            process.StandardOutput.ReadToEndAsync();
            string error = process.StandardError.ReadToEnd();
            process.WaitForExit();
            if (process.ExitCode != 0 || !File.Exists(flac))
            {
                if (File.Exists(flac)) File.Delete(flac);
                throw new Exception("ffmpeg failed: " + error);
            }
        }
    }
}

// Deterministic integer test signals. At(channel, index, bits) is random access, so long files
// can be verified without storing their source.
sealed class Signal
{
    public readonly string Kind;
    public readonly uint Seed;
    public readonly int Shift;
    public Signal(string kind, uint seed, int shift = 0) { Kind = kind; Seed = seed; Shift = shift; }

    public long At(int ch, long i, int bits)
    {
        return Shift > 0 ? Base(ch, i, bits - Shift) << Shift : Base(ch, i, bits);
    }

    long Base(int ch, long i, int bits)
    {
        switch (Kind)
        {
            case "silence": return 0;
            case "square": return Square(ch, i, bits);
            case "noise": return Noise(ch, i, bits) * 7 / 8;
            case "mix":
                int segment = (int)((i / 3000) % 7);
                if (segment == 0) return 0;
                if (segment == 3) return Noise(ch, i, bits) / 2;
                if (segment == 5) return Square(ch, i, bits);
                return Music(ch, i, bits);
            default: return Music(ch, i, bits);
        }
    }

    static long Square(int ch, long i, int bits) { return ((i / 32 + ch) & 1) == 0 ? (1L << (bits - 1)) - 1 : -(1L << (bits - 1)); }

    long Noise(int ch, long i, int bits) { return (long)(int)(uint)Mix(Key(ch, i)) >> (32 - bits); }

    long Music(int ch, long i, int bits)
    {
        long j = i % 132300;
        uint chirp = (uint)((ulong)(j * 5840000L + j * j * 1448L) + (ulong)ch * 0x20000000UL);
        uint tone = (uint)((ulong)i * (ulong)(21424000L * (ch % 3 + 1)));
        int v16 = ((Tone(chirp) * (ch == 1 ? 115 : 128)) >> 8) + (Tone(tone) >> 2) + ((int)(short)Mix(Key(ch, i)) >> 6);
        if (bits == 16) return v16;
        if (bits < 16) return v16 >> (16 - bits);
        long low = (long)(Mix(Key(ch + 16, i)) & ((1UL << (bits - 16)) - 1));
        return ((long)v16 << (bits - 16)) + low;
    }

    // Parabolic sine approximation of a 32-bit phase, in [-32767, 32767].
    static int Tone(uint phase)
    {
        int x = (short)(phase >> 16);
        int ax = x < 0 ? -x : x;
        int y = (x * (32768 - ax)) >> 13;
        return y > 32767 ? 32767 : y < -32767 ? -32767 : y;
    }

    ulong Key(int ch, long i) { return ((ulong)Seed << 44) ^ ((ulong)ch << 38) ^ (ulong)i; }

    static ulong Mix(ulong z)
    {
        z += 0x9E3779B97F4A7C15UL;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
        return z ^ (z >> 31);
    }
}

// Independent bitwise CRCs so encoder output does not reuse the decoder's tables.
static class TestCrc
{
    public static int Crc8(byte[] data, int offset, int count)
    {
        int crc = 0;
        for (int i = offset; i < offset + count; i++)
        {
            crc ^= data[i];
            for (int b = 0; b < 8; b++) crc = (crc & 0x80) != 0 ? ((crc << 1) ^ 0x07) & 0xFF : (crc << 1) & 0xFF;
        }
        return crc;
    }

    public static int Crc16(byte[] data, int offset, int count)
    {
        int crc = 0;
        for (int i = offset; i < offset + count; i++)
        {
            crc ^= data[i] << 8;
            for (int b = 0; b < 8; b++) crc = (crc & 0x8000) != 0 ? ((crc << 1) ^ 0x8005) & 0xFFFF : (crc << 1) & 0xFFFF;
        }
        return crc;
    }
}

sealed class BitWriter
{
    byte[] data = new byte[4096];
    int length;
    ulong acc;
    int accBits;

    public int ByteLength { get { return length; } }
    public byte[] Data { get { return data; } }

    public void Put(ulong value, int n)
    {
        if (n == 0) return;
        if (n > 32) { Put(value >> 32, n - 32); Put(value & 0xFFFFFFFFUL, 32); return; }
        acc = (acc << n) | (value & ((1UL << n) - 1));
        accBits += n;
        while (accBits >= 8)
        {
            accBits -= 8;
            if (length == data.Length) Array.Resize(ref data, data.Length * 2);
            data[length++] = (byte)(acc >> accBits);
        }
    }

    public void Signed(long value, int n) { Put((ulong)value, n); }
    public void Unary(long zeros) { while (zeros >= 32) { Put(0, 32); zeros -= 32; } Put(1, (int)zeros + 1); }
    public void Align() { if (accBits > 0) Put(0, 8 - accBits); }
    public byte[] ToArray() { Align(); var r = new byte[length]; Array.Copy(data, r, length); return r; }
}

sealed class EncodeOptions
{
    public int Bits = 16, SampleRate = 44100, BlockSize = 4096;
    public int[] VariableSizes;
    // -1 independent, 8 left/side, 9 right/side, 10 mid/side, 11 cycles every mode per frame.
    public int StereoMode = -1;
    // verbatim, fixedN, lpcN, auto (best fixed) or cycle (rotates every kind per frame).
    public string Predictor = "auto";
    public int LpcPrecision = 12, LpcShift = 9, PartitionOrder = 4;
    public bool Rice5, Escape, Wasted = true, TotalSamples = true, HeaderBits = true, ExtraBlocks;
    // Forced sample rate code: 0 defers to STREAMINFO, 12 kHz, 13 Hz, 14 tens of Hz, -1 automatic.
    public int RateCode = -1;
    public int SeekEvery;
    public byte[] Comment;
    public string Fault;
}

// Minimal FLAC encoder for decoder coverage. Written for clarity rather than compression.
static class TestEncoder
{
    static readonly string[] Cycle = { "verbatim", "fixed0", "fixed1", "fixed2", "fixed3", "fixed4", "lpc1", "lpc8", "lpc32", "lpc12" };

    public static byte[] VorbisComment(string vendor, string[] entries)
    {
        var ms = new MemoryStream();
        Action<byte[]> put = b => { ms.Write(BitConverter.GetBytes(b.Length), 0, 4); ms.Write(b, 0, b.Length); };
        put(Encoding.UTF8.GetBytes(vendor));
        ms.Write(BitConverter.GetBytes(entries.Length), 0, 4);
        foreach (string e in entries) put(Encoding.UTF8.GetBytes(e));
        return ms.ToArray();
    }

    public static byte[] Encode(long[][] src, EncodeOptions o)
    {
        int channels = src.Length;
        long total = src[0].Length;
        var frames = new List<byte[]>();
        var starts = new List<long>();
        var sizes = new List<int>();
        long start = 0;
        int index = 0;
        while (start < total)
        {
            int n = o.VariableSizes != null ? o.VariableSizes[index % o.VariableSizes.Length] : o.BlockSize;
            n = (int)Math.Min(n, total - start);
            long number = o.VariableSizes != null ? start : index;
            frames.Add(EncodeFrame(src, start, n, number, o, index));
            starts.Add(start);
            sizes.Add(n);
            start += n;
            index++;
        }
        int minBlock = int.MaxValue, maxBlock = 0, minFrame = int.MaxValue, maxFrame = 0;
        for (int i = 0; i < frames.Count; i++)
        {
            if (i < frames.Count - 1 || frames.Count == 1) { minBlock = Math.Min(minBlock, sizes[i]); maxBlock = Math.Max(maxBlock, sizes[i]); }
            minFrame = Math.Min(minFrame, frames[i].Length);
            maxFrame = Math.Max(maxFrame, frames[i].Length);
        }
        if (o.VariableSizes == null) minBlock = maxBlock = Math.Max(maxBlock, Math.Min(o.BlockSize, (int)total));
        if (o.VariableSizes != null) maxBlock = Math.Max(maxBlock, sizes[sizes.Count - 1]);

        var blocks = new List<KeyValuePair<int, byte[]>>();
        var info = new BitWriter();
        info.Put((ulong)minBlock, 16); info.Put((ulong)maxBlock, 16);
        info.Put((ulong)minFrame, 24); info.Put((ulong)maxFrame, 24);
        info.Put((ulong)o.SampleRate, 20); info.Put((ulong)(channels - 1), 3); info.Put((ulong)(o.Bits - 1), 5);
        info.Put(o.TotalSamples ? (ulong)total : 0, 36);
        info.Put(0, 64); info.Put(0, 64);
        blocks.Add(new KeyValuePair<int, byte[]>(0, info.ToArray()));
        if (o.ExtraBlocks) blocks.Add(new KeyValuePair<int, byte[]>(2, Encoding.ASCII.GetBytes("tstXapplication data")));
        if (o.SeekEvery > 0)
        {
            var table = new BitWriter();
            long next = 0, offset = 0;
            int points = 0;
            for (int i = 0; i < frames.Count; i++)
            {
                if (starts[i] + sizes[i] > next)
                {
                    table.Put((ulong)starts[i], 64); table.Put((ulong)offset, 64); table.Put((ulong)sizes[i], 16);
                    next = (starts[i] / o.SeekEvery + 1) * o.SeekEvery;
                    points++;
                }
                offset += frames[i].Length;
            }
            table.Put(ulong.MaxValue, 64); table.Put(0, 64); table.Put(0, 16);
            blocks.Add(new KeyValuePair<int, byte[]>(3, table.ToArray()));
        }
        if (o.Comment != null) blocks.Add(new KeyValuePair<int, byte[]>(4, o.Comment));
        if (o.ExtraBlocks)
        {
            blocks.Add(new KeyValuePair<int, byte[]>(6, new byte[64]));
            blocks.Add(new KeyValuePair<int, byte[]>(1, new byte[100]));
        }
        var ms = new MemoryStream();
        ms.Write(Encoding.ASCII.GetBytes("fLaC"), 0, 4);
        for (int i = 0; i < blocks.Count; i++)
        {
            byte[] b = blocks[i].Value;
            ms.WriteByte((byte)(blocks[i].Key | (i == blocks.Count - 1 ? 0x80 : 0)));
            ms.WriteByte((byte)(b.Length >> 16)); ms.WriteByte((byte)(b.Length >> 8)); ms.WriteByte((byte)b.Length);
            ms.Write(b, 0, b.Length);
        }
        foreach (byte[] f in frames) ms.Write(f, 0, f.Length);
        return ms.ToArray();
    }

    public static void WriteHeader(BitWriter w, bool variable, long number, int n, int rate, int channelCode, int bits, int rateCode, bool headerRate, bool headerBits)
    {
        int start = w.ByteLength;
        w.Put(0x3FFE, 14); w.Put(0, 1); w.Put(variable ? 1UL : 0, 1);
        int blockCode;
        if (n == 192) blockCode = 1;
        else if (n == 576 || n == 1152 || n == 2304 || n == 4608) blockCode = 2 + Log2(n / 576);
        else if (n >= 256 && n <= 32768 && (n & (n - 1)) == 0) blockCode = 8 + Log2(n / 256);
        else blockCode = n <= 256 ? 6 : 7;
        int[] table = { 0, 88200, 176400, 192000, 8000, 16000, 22050, 24000, 32000, 44100, 48000, 96000 };
        int code = -1;
        if (rateCode >= 0) code = rateCode;
        else
        {
            for (int i = 1; i < table.Length; i++) if (table[i] == rate) code = i;
            if (code < 0) code = rate % 1000 == 0 && rate / 1000 <= 255 ? 12 : rate <= 65535 ? 13 : rate % 10 == 0 && rate / 10 <= 65535 ? 14 : 0;
        }
        if (!headerRate) code = 0;
        int bitsCode = 0;
        if (headerBits)
        {
            int[] depths = { 0, 8, 12, 0, 16, 20, 24, 32 };
            for (int i = 1; i < depths.Length; i++) if (depths[i] == bits) bitsCode = i;
        }
        w.Put((ulong)blockCode, 4); w.Put((ulong)code, 4); w.Put((ulong)channelCode, 4); w.Put((ulong)bitsCode, 3); w.Put(0, 1);
        if (number < 0x80) w.Put((ulong)number, 8);
        else
        {
            int bytes = number < 0x800 ? 2 : number < 0x10000 ? 3 : number < 0x200000 ? 4 : number < 0x4000000 ? 5 : number < 0x80000000L ? 6 : 7;
            int lead = bytes == 7 ? 0xFE : ((0xFF00 >> bytes) & 0xFF) | (int)(number >> (6 * (bytes - 1)));
            w.Put((ulong)lead, 8);
            for (int i = bytes - 2; i >= 0; i--) w.Put((ulong)(0x80 | ((number >> (6 * i)) & 0x3F)), 8);
        }
        if (blockCode == 6) w.Put((ulong)(n - 1), 8);
        else if (blockCode == 7) w.Put((ulong)(n - 1), 16);
        if (code == 12) w.Put((ulong)(rate / 1000), 8);
        else if (code == 13) w.Put((ulong)rate, 16);
        else if (code == 14) w.Put((ulong)(rate / 10), 16);
        w.Put((ulong)TestCrc.Crc8(w.Data, start, w.ByteLength - start), 8);
    }

    static int Log2(int v) { int r = 0; while (v > 1) { v >>= 1; r++; } return r; }

    static byte[] EncodeFrame(long[][] src, long start, int n, long number, EncodeOptions o, int index)
    {
        int channels = src.Length;
        var w = new BitWriter();
        int channelCode = channels - 1;
        if (channels == 2 && o.StereoMode >= 0) channelCode = o.StereoMode == 11 ? (index % 4 == 0 ? 1 : 7 + index % 4) : o.StereoMode;
        WriteHeader(w, o.VariableSizes != null, number, n, o.SampleRate, channelCode, o.Bits, o.RateCode, o.RateCode != 0, o.HeaderBits);
        var data = new long[channels][];
        var extra = new int[channels];
        for (int c = 0; c < channels; c++) { data[c] = new long[n]; Array.Copy(src[c], start, data[c], 0, n); }
        if (channelCode >= 8)
        {
            long[] l = data[0], r = data[1], a = new long[n], b = new long[n];
            for (int i = 0; i < n; i++)
            {
                long side = l[i] - r[i];
                if (channelCode == 8) { a[i] = l[i]; b[i] = side; }
                else if (channelCode == 9) { a[i] = side; b[i] = r[i]; }
                else { a[i] = (l[i] + r[i]) >> 1; b[i] = side; }
            }
            data[0] = a; data[1] = b;
            extra[channelCode == 9 ? 0 : 1] = 1;
        }
        for (int c = 0; c < channels; c++) EncodeSubframe(w, data[c], n, o.Bits + extra[c], o, index + c);
        w.Align();
        w.Put((ulong)TestCrc.Crc16(w.Data, 0, w.ByteLength), 16);
        return w.ToArray();
    }

    static void EncodeSubframe(BitWriter w, long[] d, int n, int bits, EncodeOptions o, int index)
    {
        string predictor = o.Predictor == "cycle" ? Cycle[index % Cycle.Length] : o.Predictor;
        bool equal = true;
        long any = 0;
        for (int i = 0; i < n; i++) { any |= d[i]; if (d[i] != d[0]) equal = false; }
        if (equal && predictor != "verbatim" && o.Fault == null)
        {
            w.Put(0, 8);
            w.Signed(d[0], bits);
            return;
        }
        int wasted = 0;
        if (o.Wasted && any != 0) while (((any >> wasted) & 1) == 0) wasted++;
        if (o.Fault == "wasted") wasted = 0;
        if (wasted > 0)
        {
            var shifted = new long[n];
            for (int i = 0; i < n; i++) shifted[i] = d[i] >> wasted;
            d = shifted;
            bits -= wasted;
        }
        int order = 0;
        long[] coefficients = null;
        int precision = o.LpcPrecision, shift = o.LpcShift;
        bool lpc = predictor.StartsWith("lpc");
        if (predictor == "auto") order = BestFixed(d, n);
        else if (predictor.StartsWith("fixed")) order = int.Parse(predictor.Substring(5));
        else if (lpc) order = int.Parse(predictor.Substring(3));
        order = Math.Min(order, n);
        long[] residual = null;
        if (predictor != "verbatim")
        {
            if (lpc) coefficients = Coefficients(order, precision, shift);
            residual = new long[n];
            for (int i = order; i < n; i++)
            {
                long prediction = 0;
                if (lpc) { for (int j = 0; j < order; j++) prediction += coefficients[j] * d[i - 1 - j]; prediction >>= shift; }
                else prediction = FixedPrediction(d, i, order);
                residual[i] = d[i] - prediction;
                if (residual[i] > int.MaxValue || residual[i] < int.MinValue) { residual = null; break; }
            }
        }
        if (residual == null)
        {
            w.Put(0, 1); w.Put(1, 6);
            PutWasted(w, wasted);
            for (int i = 0; i < n; i++) w.Signed(d[i], bits);
            return;
        }
        w.Put(0, 1);
        w.Put(o.Fault == "subtype" ? 2UL : lpc ? (ulong)(31 + order) : (ulong)(8 + order), 6);
        if (o.Fault == "wasted") { w.Put(1, 1); w.Unary(bits); }
        else PutWasted(w, wasted);
        for (int i = 0; i < order; i++) w.Signed(d[i], bits);
        if (lpc)
        {
            w.Put(o.Fault == "precision" ? 15UL : (ulong)(precision - 1), 4);
            w.Signed(o.Fault == "negshift" ? -1 : shift, 5);
            for (int j = 0; j < order; j++) w.Signed(coefficients[j], precision);
        }
        EncodeResidual(w, residual, n, order, o);
    }

    static void PutWasted(BitWriter w, int wasted) { if (wasted > 0) { w.Put(1, 1); w.Unary(wasted - 1); } else w.Put(0, 1); }

    static int BestFixed(long[] d, int n)
    {
        int best = 0;
        long bestSum = long.MaxValue;
        for (int order = 0; order <= 4 && order <= n; order++)
        {
            long sum = 0;
            for (int i = order; i < n; i++) sum += Math.Abs(d[i] - FixedPrediction(d, i, order));
            if (sum < bestSum) { bestSum = sum; best = order; }
        }
        return best;
    }

    static long FixedPrediction(long[] d, int i, int order)
    {
        switch (order)
        {
            case 0: return 0;
            case 1: return d[i - 1];
            case 2: return 2 * d[i - 1] - d[i - 2];
            case 3: return 3 * d[i - 1] - 3 * d[i - 2] + d[i - 3];
            default: return 4 * d[i - 1] - 6 * d[i - 2] + 4 * d[i - 3] - d[i - 4];
        }
    }

    // Any quantised coefficients are lossless. These approximate a second-order predictor with
    // small extra taps so every coefficient position matters.
    static long[] Coefficients(int order, int precision, int shift)
    {
        long q = 1L << shift, max = (1L << (precision - 1)) - 1, min = -(1L << (precision - 1));
        var c = new long[order];
        for (int j = 0; j < order; j++)
        {
            long v = j == 0 ? (order == 1 ? q * 15 / 16 : q * 29 / 16) : j == 1 ? -(q * 13 / 16) : ((j % 3) - 1) * (q >> 6);
            c[j] = Math.Max(min, Math.Min(max, v));
        }
        return c;
    }

    static void EncodeResidual(BitWriter w, long[] e, int n, int order, EncodeOptions o)
    {
        int po = o.PartitionOrder;
        while (po > 0 && (((n >> po) << po) != n || (n >> po) < order)) po--;
        if (o.Fault == "partition") po = 15;
        int partitions = 1 << po, size = n >> po;
        var ks = new int[partitions];
        var widths = new int[partitions];
        bool needFive = o.Rice5;
        for (int p = 0; p < partitions; p++)
        {
            int from = p == 0 ? order : p * size, to = (p + 1) * size;
            if (o.Fault == "partition") { from = 0; to = 0; }
            ulong sum = 0;
            int width = 0;
            for (int i = from; i < to; i++)
            {
                sum += Zigzag(e[i]);
                width = Math.Max(width, SignedWidth(e[i]));
            }
            int count = Math.Max(1, to - from);
            ulong mean = sum / (ulong)count;
            int k = 0;
            while (k < 30 && (mean >> (k + 1)) > 0) k++;
            ks[p] = k;
            widths[p] = width;
            if (k > 14) needFive = true;
        }
        int method = needFive ? 1 : 0;
        w.Put(o.Fault == "method" ? 2UL : (ulong)method, 2);
        w.Put((ulong)po, 4);
        int parameterBits = method == 0 ? 4 : 5, escape = method == 0 ? 15 : 31;
        for (int p = 0; p < partitions; p++)
        {
            int from = p == 0 ? order : p * size, to = (p + 1) * size;
            if (o.Escape && p % 3 == 1 && widths[p] <= 31)
            {
                w.Put((ulong)escape, parameterBits);
                w.Put((ulong)widths[p], 5);
                if (widths[p] > 0) for (int i = from; i < to; i++) w.Signed(e[i], widths[p]);
                continue;
            }
            int k = ks[p];
            w.Put((ulong)k, parameterBits);
            for (int i = from; i < to; i++)
            {
                ulong u = Zigzag(e[i]);
                w.Unary((long)(u >> k));
                if (k > 0) w.Put(u & ((1UL << k) - 1), k);
            }
        }
    }

    static int SignedWidth(long v)
    {
        if (v == 0) return 0;
        int w = 1;
        while (v < -(1L << (w - 1)) || v > (1L << (w - 1)) - 1) w++;
        return w;
    }

    static ulong Zigzag(long v) { return v >= 0 ? (ulong)v << 1 : ((ulong)(-(v + 1)) << 1) | 1; }
}
